INSERT INTO v2_array_dwd_rebuild_20261123.dwd_stock_research_report WITH version_flags AS (SELECT *,max(toUInt8(_observation_versions>1)) OVER (PARTITION BY `ts_code`,`report_date`,`org_name`,`report_title`,`author_name`,`quarter`,`report_type`,`classify`,`create_time`) AS _key_conflict FROM (SELECT *,uniqExact(source_record_hash) OVER (PARTITION BY `ts_code`,`report_date`,`org_name`,`report_title`,`author_name`,`quarter`,`report_type`,`classify`,`create_time`,sys_from) AS _observation_versions FROM v2_array_dwd_rebuild_20261123.dwd_stock_research_report_unresolved)) SELECT `ts_code`,`name`,`report_date`,`report_title`,`report_type`,`classify`,`org_name`,`author_name`,`quarter`,`op_rt`,`op_pr`,`tp`,`np`,`eps`,`pe`,`rd`,`roe`,`ev_ebitda`,`rating`,`max_price`,`min_price`,`imp_dg`,`create_time`,`instrument_id`,`instrument_type`,`exchange`,`source_code`,`event_date`,`available_trade_date`,`sys_from`,`sys_to`,`source`,`source_table`,`source_batch_id`,`source_record_hash`,`forecast_period_end` FROM version_flags WHERE _key_conflict=0